/**
 * TerminalHarness wires openShell() to a headless xterm Terminal so tests can
 * assert against deterministic terminal screen state.
 */
import { Terminal } from "@xterm/headless";
const SETTLE_MS = 50;
const POLL_MS = 20;
const DEFAULT_WAIT_TIMEOUT_MS = 5_000;
export class TerminalHarness {
    term;
    shell;
    typing = false;
    disposed = false;
    constructor(kernel, options) {
        const cols = options?.cols ?? 80;
        const rows = options?.rows ?? 24;
        this.term = new Terminal({ cols, rows, allowProposedApi: true });
        this.shell = kernel.openShell({
            cols,
            rows,
            env: options?.env,
            cwd: options?.cwd,
        });
        this.shell.onData = (data) => {
            this.term.write(data);
        };
    }
    async type(input) {
        if (this.typing) {
            throw new Error("TerminalHarness.type() called while previous type() is still in-flight");
        }
        this.typing = true;
        try {
            await this.typeInternal(input);
        }
        finally {
            this.typing = false;
        }
    }
    typeInternal(input) {
        return new Promise((resolve) => {
            let timer = null;
            const originalOnData = this.shell.onData;
            const resetTimer = () => {
                if (timer !== null)
                    clearTimeout(timer);
                timer = setTimeout(() => {
                    this.shell.onData = originalOnData;
                    resolve();
                }, SETTLE_MS);
            };
            this.shell.onData = (data) => {
                this.term.write(data);
                resetTimer();
            };
            resetTimer();
            this.shell.write(input);
        });
    }
    screenshotTrimmed() {
        const buf = this.term.buffer.active;
        const lines = [];
        for (let row = 0; row < this.term.rows; row++) {
            const line = buf.getLine(buf.viewportY + row);
            lines.push(line ? line.translateToString(true) : "");
        }
        while (lines.length > 0 && lines[lines.length - 1] === "") {
            lines.pop();
        }
        return lines.join("\n");
    }
    line(row) {
        const buf = this.term.buffer.active;
        const line = buf.getLine(buf.viewportY + row);
        return line ? line.translateToString(true) : "";
    }
    async waitFor(text, occurrence = 1, timeoutMs = DEFAULT_WAIT_TIMEOUT_MS) {
        const deadline = Date.now() + timeoutMs;
        while (true) {
            const screen = this.screenshotTrimmed();
            let count = 0;
            let idx = -1;
            while (true) {
                idx = screen.indexOf(text, idx + 1);
                if (idx === -1)
                    break;
                count++;
                if (count >= occurrence)
                    return;
            }
            if (Date.now() >= deadline) {
                throw new Error(`waitFor("${text}", ${occurrence}) timed out after ${timeoutMs}ms.\n` +
                    `Expected: "${text}" (occurrence ${occurrence})\n` +
                    `Screen:\n${screen}`);
            }
            await new Promise((resolve) => setTimeout(resolve, POLL_MS));
        }
    }
    async exit() {
        this.shell.write("\x04");
        return this.shell.wait();
    }
    async dispose() {
        if (this.disposed)
            return;
        this.disposed = true;
        try {
            this.shell.kill();
            await Promise.race([
                this.shell.wait(),
                new Promise((resolve) => setTimeout(resolve, 500)),
            ]);
        }
        catch {
            // Shell may already be gone.
        }
        this.term.dispose();
    }
}
